sys_script_include.script:
var NowTrainingScript = Class.create();
NowTrainingScript.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    enrolled: function(trainingId, userId) {
        var gr = new GlideRecord('x_221517_nowtrai_0_enrollment');
        gr.addQuery('x_221517_nowtrai_0_training', trainingId);
        gr.addQuery('x_221517_nowtrai_0_enrollment_student', userId);
        gr.query();
        return gr.hasNext();
    },

    getCourseEnrollments: function(courseId, userId) {
        var ga = new GlideAggregate('x_221517_nowtrai_0_enrollment');
        ga.addQuery('x_221517_nowtrai_0_enrollment_student', userId);
        ga.addQuery('x_221517_nowtrai_0_training.x_221517_nowtrai_0_training_course', courseId);
        ga.addAggregate('COUNT');
        ga.query();
        return ga.next() ? ga.getAggregate('COUNT') : 0;
    },

    getEnrolled: function(trainingId) {
        var ga = new GlideAggregate('x_221517_nowtrai_0_enrollment');
        ga.addQuery('x_221517_nowtrai_0_training', trainingId);
        ga.addAggregate('COUNT');
        ga.query();
        return ga.next() ? ga.getAggregate('COUNT') : 0;
    },

    getAvailableTrainings: function() {
        var userId = gs.getUserID();
        var availableTrainings = [];

        var gr = new GlideRecord('x_221517_nowtrai_0_training');
        gr.query();

        while (gr.next()) {
            var trainingId = gr.getUniqueValue();
            var courseId = gr.course.toString();
            var trainingDate = new GlideDateTime(gr.training_date);
            var instructorId = gr.instructor.toString();

            // stry 7
            if (this.enrolled(trainingId, userId)) continue;

            // stry 8
            if (this.getCourseEnrollments(courseId, userId) >= 3) continue;

            // stry 9
            var occupied = this.getEnrolled(trainingId);
            var capacity = parseInt('gr.capacity');
            if (occupied >= capacity) continue;

            // str 10
            if (instructorId == userId) continue;

            // str 11
            var tomorrow = new GlideDateTime();
            tomorrow.addDaysLocalTime(1);
            if (trainingDate.getNumericValue() < tomorrow.getNumericValue()) continue;

            availableTrainings.push(trainingId);
        }

        return "sys_idIN" + availableTrainings.join(',');
    },

	//stry 3
    checkTrainingDate: function() {
        var courseId = this.getParameter('sysparm_course');
        var newDate = this.getParameter('sysparm_date');

		var gdt = new GlideDateTime();
		gdt.setDisplayValue(newDate);

		var formatedDate = gdt.getDate().toString(); 

        var gr = new GlideRecord('x_221517_nowtrai_0_training');
        gr.addQuery('course', courseId);
        gr.addQuery('date', 'STARTSWITH', formatedDate);
        gr.query();

		return gr.hasNext() ? "true" : "false";
    },

    type: 'NowTrainingScript'
});
